INSERT INTO experience_galleries (experience_id, eyebrow, t1, t2, copy, foot, cta) VALUES ('waterfalls', 'NATURE · INCLUDED WITH ENTRY', 'Where the', 'water falls', 'Two waterfalls, cool pools and a boardwalk under the spray, all on the nature trail your entry already covers.', 'INCLUDED IN ENTRY · ALL AGES', 'Plan your visit →') ON CONFLICT (experience_id) DO NOTHING;
INSERT INTO experience_galleries (experience_id, eyebrow, t1, t2, copy, foot, cta) VALUES ('animals', 'NATURE · INCLUDED WITH ENTRY', 'Meet the', 'locals', 'Deer on the meadow, giant tortoises and the fruit bats of Mauritius, met along the trail.', 'INCLUDED IN ENTRY · ALL AGES', 'Plan your visit →') ON CONFLICT (experience_id) DO NOTHING;
INSERT INTO experience_galleries (experience_id, eyebrow, t1, t2, copy, foot, cta) VALUES ('coloured', 'NATURE · INCLUDED WITH ENTRY', 'Every shade', 'of the island', 'The 23 Coloured Earth: volcanic dunes in reds, purples and golds.', 'INCLUDED IN ENTRY · ALL AGES', 'Plan your visit →') ON CONFLICT (experience_id) DO NOTHING;
INSERT INTO experience_galleries (experience_id, eyebrow, t1, t2, copy, foot, cta) VALUES ('trees', 'NATURE WALK · SENIORS WELCOME', 'Take it', 'slowly', 'Shaded paths under endemic trees, beside the stream, at the pace that suits you. A favourite of our senior guests.', 'INCLUDED IN ENTRY · GENTLE PATHS', 'Plan your visit →') ON CONFLICT (experience_id) DO NOTHING;
INSERT INTO experience_galleries (experience_id, eyebrow, t1, t2, copy, foot, cta) VALUES ('playground', 'KIDS PARK', 'Let them', 'run', 'Slides, towers and open lawns for the little ones while the grown-ups catch their breath.', 'KIDS PARK · ALL AGES', 'Plan your visit →') ON CONFLICT (experience_id) DO NOTHING;
